functions {
  real dynamic_temporary(real x) {
    if (x > 0) {
      array[1] real temporary = rep_array(x, 1);
      return sum(temporary);
    } else {
      array[2] real temporary = rep_array(x, 2);
      return sum(temporary);
    }
  }
}
